import{_ as a,o as t,c as i,a2 as o}from"./chunks/framework.Dsf4_p3t.js";const p=JSON.parse('{"title":"Frequently Asked Questions","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1787671700000}'),s={name:"guide/faq.md"};function r(d,e,l,n,h,c){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h1><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><h3 id="what-is-neoflux" tabindex="-1">What is NeoFlux? <a class="header-anchor" href="#what-is-neoflux" aria-label="Permalink to &quot;What is NeoFlux?&quot;">​</a></h3><p>NeoFlux is a lightweight, cross-platform C++20 UI framework with a two-layer architecture: an Application layer running business logic and the Taitank flex layout engine, and a Render layer consuming render commands via tgfx (mobile) or GLFW (desktop).</p><h3 id="why-c-20" tabindex="-1">Why C++20? <a class="header-anchor" href="#why-c-20" aria-label="Permalink to &quot;Why C++20?&quot;">​</a></h3><p>C++20 enables coroutines (<code>co_await</code>), concepts, <code>std::span</code>, designated initializers, and <code>std::bit_ceil</code>. These are used throughout the framework for clean, efficient code.</p><h3 id="is-neoflux-production-ready" tabindex="-1">Is NeoFlux production-ready? <a class="header-anchor" href="#is-neoflux-production-ready" aria-label="Permalink to &quot;Is NeoFlux production-ready?&quot;">​</a></h3><p>NeoFlux is under active development. The core architecture (widget tree, flex layout, render pipeline, input dispatch) is functional. See the GitHub issues for current limitations.</p><h2 id="building" tabindex="-1">Building <a class="header-anchor" href="#building" aria-label="Permalink to &quot;Building&quot;">​</a></h2><h3 id="how-do-i-build-neoflux" tabindex="-1">How do I build NeoFlux? <a class="header-anchor" href="#how-do-i-build-neoflux" aria-label="Permalink to &quot;How do I build NeoFlux?&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -j</span></span></code></pre></div><p>Examples and tests are off by default. Enable them with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DNEOFLUX_BUILD_EXAMPLES=ON</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DNEOFLUX_BUILD_TESTS=ON</span></span></code></pre></div><h3 id="why-is-the-build-slow-the-first-time" tabindex="-1">Why is the build slow the first time? <a class="header-anchor" href="#why-is-the-build-slow-the-first-time" aria-label="Permalink to &quot;Why is the build slow the first time?&quot;">​</a></h3><p>NeoFlux uses FetchContent to download and build third-party dependencies (glog, gflags, glfw, taitank, freetype, gtest). Subsequent builds are fast because dependencies are cached in <code>thirdparty/_deps/</code>.</p><h3 id="how-do-i-cross-compile" tabindex="-1">How do I cross-compile? <a class="header-anchor" href="#how-do-i-cross-compile" aria-label="Permalink to &quot;How do I cross-compile?&quot;">​</a></h3><p>Set the CMake toolchain file for your target platform. NeoFlux uses platform macros (<code>NEOFLUX_PLATFORM_DESKTOP</code>, <code>NEOFLUX_PLATFORM_MOBILE</code>, <code>NEOFLUX_PLATFORM_WINDOWS</code>, etc.) to select the appropriate backend.</p><h2 id="rendering" tabindex="-1">Rendering <a class="header-anchor" href="#rendering" aria-label="Permalink to &quot;Rendering&quot;">​</a></h2><h3 id="what-render-backends-are-supported" tabindex="-1">What render backends are supported? <a class="header-anchor" href="#what-render-backends-are-supported" aria-label="Permalink to &quot;What render backends are supported?&quot;">​</a></h3><ul><li><strong>Vulkan</strong> (default) — via tgfx</li><li><strong>OpenGL</strong> — via tgfx/GLFW</li><li><strong>CPU</strong> — software rendering (fallback)</li></ul><p>Select with <code>--render_backend=vulkan|gl|cpu</code>.</p><h3 id="why-is-my-window-black" tabindex="-1">Why is my window black? <a class="header-anchor" href="#why-is-my-window-black" aria-label="Permalink to &quot;Why is my window black?&quot;">​</a></h3><p>Common causes:</p><ol><li><strong>No font loaded</strong> — Text widgets need a <code>.ttf</code>/<code>.otf</code> file in the font directory. Call <code>app.SetFontDir(&quot;./fonts/&quot;)</code> before <code>Init()</code>.</li><li><strong>No route pushed</strong> — All examples require <code>RouteRegistry::RegisterRoute()</code> followed by <code>app.PushRoute(&quot;/&quot;)</code>.</li><li><strong>Window not exposed</strong> — The first frame may need a resize or focus event on some platforms.</li></ol><h3 id="why-is-text-garbled" tabindex="-1">Why is text garbled? <a class="header-anchor" href="#why-is-text-garbled" aria-label="Permalink to &quot;Why is text garbled?&quot;">​</a></h3><p>The font file does not contain the glyphs you are trying to render. Use a font that supports your character set (e.g., NotoSansSC for CJK).</p><h2 id="widgets" tabindex="-1">Widgets <a class="header-anchor" href="#widgets" aria-label="Permalink to &quot;Widgets&quot;">​</a></h2><h3 id="how-do-i-create-a-custom-widget" tabindex="-1">How do I create a custom widget? <a class="header-anchor" href="#how-do-i-create-a-custom-widget" aria-label="Permalink to &quot;How do I create a custom widget?&quot;">​</a></h3><p>Inherit from <code>Widget</code> (or <code>StatelessWidget</code>/<code>StatefulWidget</code>) and override the relevant virtual functions: <code>Build()</code>, <code>OnMeasure()</code>, <code>Paint()</code>, and event handlers. See the <a href="./widgets">Widget System</a> guide.</p><h3 id="what-is-the-difference-between-markneedsbuild-and-markframedirty" tabindex="-1">What is the difference between <code>MarkNeedsBuild()</code> and <code>MarkFrameDirty()</code>? <a class="header-anchor" href="#what-is-the-difference-between-markneedsbuild-and-markframedirty" aria-label="Permalink to &quot;What is the difference between `MarkNeedsBuild()` and `MarkFrameDirty()`?&quot;">​</a></h3><ul><li><code>MarkNeedsBuild()</code> — marks the widget for rebuild on the next frame (children may change).</li><li><code>MarkFrameDirty()</code> — triggers a layout/paint cycle without rebuilding widgets. Use this for paint-time changes (e.g., drag offsets, scroll position).</li></ul><h3 id="why-doesn-t-my-draggable-follow-the-cursor" tabindex="-1">Why doesn&#39;t my Draggable follow the cursor? <a class="header-anchor" href="#why-doesn-t-my-draggable-follow-the-cursor" aria-label="Permalink to &quot;Why doesn&#39;t my Draggable follow the cursor?&quot;">​</a></h3><p>Ensure you are not calling <code>MarkNeedsBuild()</code> in <code>OnPointerMove()</code> — the drag offset is paint-time only. The framework calls <code>MarkFrameDirty()</code> automatically on pointer events.</p><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h2><h3 id="why-is-my-widget-not-visible" tabindex="-1">Why is my widget not visible? <a class="header-anchor" href="#why-is-my-widget-not-visible" aria-label="Permalink to &quot;Why is my widget not visible?&quot;">​</a></h3><ul><li>The widget has zero size (check <code>OnMeasure()</code> return value).</li><li>The widget is outside the viewport (check flex constraints).</li><li>The widget is clipped by a <code>ScrollView</code> or <code>ClipRect</code>.</li></ul><h3 id="how-do-i-make-a-widget-fill-available-space" tabindex="-1">How do I make a widget fill available space? <a class="header-anchor" href="#how-do-i-make-a-widget-fill-available-space" aria-label="Permalink to &quot;How do I make a widget fill available space?&quot;">​</a></h3><p>Use <code>Expanded</code> (sets <code>flex_grow</code>) or set <code>SetWidth(0)</code> with <code>flex_grow &gt; 0</code> in a flex container.</p><h2 id="threading" tabindex="-1">Threading <a class="header-anchor" href="#threading" aria-label="Permalink to &quot;Threading&quot;">​</a></h2><h3 id="is-neoflux-thread-safe" tabindex="-1">Is NeoFlux thread-safe? <a class="header-anchor" href="#is-neoflux-thread-safe" aria-label="Permalink to &quot;Is NeoFlux thread-safe?&quot;">​</a></h3><p>The widget tree is only accessed from the main thread. The render layer runs on a separate thread and communicates via the SPSC ring queue. Do not touch widgets from the render thread.</p><h3 id="how-do-coroutines-work" tabindex="-1">How do coroutines work? <a class="header-anchor" href="#how-do-coroutines-work" aria-label="Permalink to &quot;How do coroutines work?&quot;">​</a></h3><p>NeoFlux provides a <code>Task&lt;T&gt;</code> coroutine type with <code>co_await Yield()</code> (next frame) and <code>co_await Sleep(duration)</code>. Coroutines are scheduled on the main thread by <code>EventLoop</code>. Use <code>std::weak_ptr</code> to guard against widget destruction during <code>co_await</code>.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="the-application-crashes-on-startup" tabindex="-1">The application crashes on startup <a class="header-anchor" href="#the-application-crashes-on-startup" aria-label="Permalink to &quot;The application crashes on startup&quot;">​</a></h3><p>Check:</p><ol><li>Font directory exists and contains valid font files.</li><li><code>Init()</code> is called before <code>Run()</code>.</li><li>A route is registered and pushed.</li><li>The render backend is supported on your platform.</li></ol><h3 id="clang-tidy-reports-warnings" tabindex="-1">clang-tidy reports warnings <a class="header-anchor" href="#clang-tidy-reports-warnings" aria-label="Permalink to &quot;clang-tidy reports warnings&quot;">​</a></h3><p>Run <code>clang-tidy -p build src/**/*.cpp</code> to check. The project aims for zero warnings. See <a href="./contributing">Contributing</a> for the full checklist.</p><h3 id="how-do-i-enable-verbose-logging" tabindex="-1">How do I enable verbose logging? <a class="header-anchor" href="#how-do-i-enable-verbose-logging" aria-label="Permalink to &quot;How do I enable verbose logging?&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./my_app</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --verbose_logging=true</span></span></code></pre></div><p>Logs are written to <code>logs/</code> by default. Use <code>--logtostderr=true</code> to output to stderr instead.</p>',52)])])}const g=a(s,[["render",r]]);export{p as __pageData,g as default};
